"""Banco revisado de la presentación del usuario; genera SQL, imágenes y metadatos."""
import json, pathlib, shutil, uuid

ROOT = pathlib.Path(__file__).resolve().parents[1]
ASSETS = ROOT / 'juegos/assets/sentidos-saladin'
ASSETS.mkdir(parents=True, exist_ok=True)
rounds = [dict(title='Receptores, dolor, gusto y olfato', questions=[]), dict(title='Audición, equilibrio y visión', questions=[])]

def add(r, kind, slide, image, prompt, answers, correct, explanation, alt):
    q = dict(id=str(uuid.uuid5(uuid.NAMESPACE_URL, f'https://alcocermed.com/sentidos-2026/{r}/{len(rounds[r-1]["questions"])+1}')), type=kind, difficulty='fácil', slide=slide, image='assets/sentidos-saladin/'+image, prompt=prompt, explanation=explanation, alt=alt)
    if kind == 'match': q['pairs'] = answers
    else: q.update(options=answers, correct=correct)
    rounds[r-1]['questions'].append(q)
    source_image = ROOT/'tmp/sentidos'/image
    if source_image.exists(): shutil.copyfile(source_image, ASSETS/image)
    else: assert (ASSETS/image).exists(), f'Falta la imagen original: {image}'

