bank = dict(source='SENTIDOS SALADIN [Autoguardado].pptx', scope='Contenido exclusivamente de la presentación aportada. Dos rondas de 20 preguntas con imágenes extraídas de la misma presentación.', rounds=rounds)
lit = lambda s: "'"+str(s).replace("'", "''")+"'"
js = lambda v: json.dumps(v, ensure_ascii=False, separators=(',',':'))
sql = ['-- SENTIDOS SALADIN: 2 rondas de 20 preguntas. Ejecutar todo en Supabase SQL Editor.', '-- Reejecutable. Solo añade o actualiza estas dos rondas; no elimina otras evaluaciones.', 'begin;']
images = {}; evaluations = []
for ri,r in enumerate(rounds,1):
    eid=str(uuid.uuid5(uuid.NAMESPACE_URL,f'https://alcocermed.com/sentidos-2026/round/{ri}'))
    title=f'Sentidos Saladin — Ronda {ri}: {r["title"]} (20 preguntas fáciles)'
    config=dict(maxQuestions=20,questionOrder=[q['id'] for q in r['questions']],enabledPowerups=['x2','time','retry'])
    evaluations.append(dict(id=eid,title=title,code=f'SENTIDOS{ri}',questionIds=config['questionOrder']))
    sql.append(f"insert into public.evaluaciones (id,titulo,asignatura,nivel,idioma,visibilidad,objetivo,codigo,publicado,created_by,created_at,updated_at,iniciado,tema,modo_sesion,config_juego) values ({lit(eid)},{lit(title)},'MORFOFUNCION','Residencia','espanol','publica',{lit(bank['scope'])},'SENTIDOS{ri}',true,'dd2eed5d-b917-4c4d-b0e7-aa6b1e57ef23',now(),now(),true,{lit('Sentidos Saladin: '+r['title'])},'individual',{lit(js(config))}::jsonb) on conflict(id) do update set titulo=excluded.titulo,tema=excluded.tema,objetivo=excluded.objetivo,publicado=true,iniciado=true,config_juego=excluded.config_juego,updated_at=now();")
    for qi,q in enumerate(r['questions'],1):
        opts = [dict(text=p[0],match=p[1]) for p in q['pairs']] if q['type']=='match' else [dict(text=t,correct=i in q['correct']) for i,t in enumerate(q['options'])]
        opts[0].update(pregunta_imagen='/juegos/'+q['image'],explicacion=q['explanation']+f" Fuente: diapositiva {q['slide']}.")
        images[q['id']]=dict(src='/juegos/'+q['image'],alt=q['alt'],credit='Imagen de la presentación SENTIDOS SALADIN')
        sql.append(f"insert into public.evaluacion_preguntas (id,evaluacion_id,tipo,texto,opciones,multiple_correctas,orden,puntos,temporizador) values ({lit(q['id'])},{lit(eid)},{lit(q['type'])},{lit(q['prompt'])},{lit(js(opts))}::jsonb,{str(q['type']=='ms').lower()},{qi},1,{90 if q['type']=='match' else 60}) on conflict(id) do update set tipo=excluded.tipo,texto=excluded.texto,opciones=excluded.opciones,multiple_correctas=excluded.multiple_correctas,orden=excluded.orden,puntos=excluded.puntos,temporizador=excluded.temporizador;")
sql += ['commit;',f"select e.titulo,count(p.id) as preguntas,count(p.id) filter (where coalesce(p.opciones->0->>'pregunta_imagen','') <> '') as con_imagen from public.evaluaciones e join public.evaluacion_preguntas p on p.evaluacion_id=e.id where e.id in ({','.join(lit(e['id']) for e in evaluations)}) group by e.id,e.titulo order by e.titulo;"]
(ROOT/'juegos/sentidos-preguntas.json').write_text(json.dumps(bank,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
(ROOT/'juegos/SUPABASE_SENTIDOS_SALADIN_40.sql').write_text('\n\n'.join(sql)+'\n',encoding='utf8')
(ROOT/'juegos/sentidos-imagenes.js').write_text('// Ilustraciones extraídas de la presentación del usuario.\nvar sentidosEvaluations = '+js(evaluations)+';\nObject.assign(nervousQuestionImages, '+js(images)+');\n',encoding='utf8')
(ASSETS/'FUENTE.txt').write_text('Imágenes extraídas de SENTIDOS SALADIN [Autoguardado].pptx, aportada por el usuario. Se conservan las ilustraciones tal como aparecen en la presentación. El banco JSON identifica la diapositiva de respaldo de cada respuesta.\n',encoding='utf8')
print(json.dumps(evaluations,ensure_ascii=False,indent=2))
